"""Anomaly Scorer — computes per-segment z-score benchmarks."""
import pandas as pd
import numpy as np


class AnomalyScorer:
    """Score events against historical segment norms."""

    def __init__(self, historical_data: pd.DataFrame):
        self._historical = historical_data
        self._benchmarks = self._compute_benchmarks()

    def _compute_benchmarks(self) -> pd.DataFrame:
        """Compute per-segment mean and std from historical data once."""
        return (
            self._historical
            .groupby('segment')
            .agg(mean=('value', 'mean'), std=('value', 'std'))
            .reset_index()
        )

    @property
    def benchmarks(self) -> pd.DataFrame:
        """Return pre-computed benchmarks."""
        return self._benchmarks

    def score_batch(self, batch: pd.DataFrame) -> pd.Series:
        """Compute z-score for each record in a batch."""
        scored = batch.merge(self._benchmarks, on='segment', how='left')
        return (scored['value'] - scored['mean']).abs() / (scored['std'] + 1e-9)

    def score_all(self, df: pd.DataFrame) -> pd.Series:
        """Compute z-score for all records at once (optimized)."""
        scored = df.merge(self._benchmarks, on='segment', how='left')
        scores = (scored['value'] - scored['mean']).abs() / (scored['std'] + 1e-9)
        return scores.reset_index(drop=True)

"""Batch Runner — iterates in batches, calling AnomalyScorer per batch."""
import pandas as pd


class BatchRunner:
    BATCH_SIZE = 500

    def __init__(self, scorer):
        self._scorer = scorer

    def run(self, df: pd.DataFrame) -> pd.Series:
        """Score all records efficiently using vectorized operations."""
        # Use optimized score_all method if available, otherwise fall back to batching
        if hasattr(self._scorer, 'score_all'):
            return self._scorer.score_all(df)

        # Fallback: score in mini-batches
        parts = []
        for start in range(0, len(df), self.BATCH_SIZE):
            batch = df.iloc[start: start + self.BATCH_SIZE]
            scores = self._scorer.score_batch(batch)
            parts.append(scores)
        return pd.concat(parts).reset_index(drop=True)

